def strip_ext(filename):
    return filename.removesuffix(".csv")

print(strip_ext("trades.csv"))
print(strip_ext("stocks.csv"))

def guests(csv_line):
    return [g.strip() for g in csv_line.split(",")]

print(guests("ann, bob, cy")[1])

def battery_pct(charge_mah, capacity_mah):
    return min(round(100 * charge_mah / capacity_mah), 100)

print(battery_pct(5200, 5000))

def nights(check_in_day, check_out_day):
    return check_out_day - check_in_day

print(nights(3, 6))

// Largest number in xs.
function biggest(xs) {
  return [...xs].sort((a, b) => a - b)[xs.length - 1];
}

console.log(biggest([9, 10, 100, 2]));

def fan_mode(temp):
    if temp > 25:
        return "off"
    return "on"

print(fan_mode(31))

def lamp_mode(lux):
    if lux > 300:
        return "off"
    return "on"

print(lamp_mode(120))

record = {"wins": 9, "losses": 0}
ratio = record["wins"] / record["losses"]
print(f"ratio {ratio}")

results = {"won": 9, "lost": 3}
rate = results["won"] / (results["won"] + results["lost"])
print(f"rate {rate}")

