def shout(msg):
    return msg.lower() + "!"

print(shout("Goal"))

def whisper(msg):
    return msg.lower() + "..."

print(whisper("Quiet"))

def to_miles(km):
    miles = km * 0.621371
    return round(miles, 2)

print(to_miles(10))

def is_boiling(temp_c):
    if temp_c < 100:
        return True
    return False

print(is_boiling(104))

def is_frozen(temp_c):
    if temp_c < 0:
        return True
    return False

print(is_frozen(-4))
